-- 41 · statutory_parameters for the income-tax computation engine (§6.11, §6.1, §7.8.2). §16 content
-- only: law parameters, no clients, no users, no demo data. Settled law is seeded verified = true;
-- the tax year 2026-27 row cites the Income-tax Act, 2025 section numbers the spec marks [verify]
-- (s.156 rebate, ss.423/424/425 interest, s.263 return), so it is seeded verified = false and the
-- Law & rules page lists it as "awaiting partner confirmation" (§6, §7.21).
--
-- Idempotent: on conflict (key, effective_from) do nothing, so re-running never overwrites a value
-- or a verification a Partner has since recorded. The same rows live in lib/domain/itr-rulesets.ts
-- (ITR_RULESET_SEED_PARAMETERS); tests/unit/itr.test.ts checks that this file matches them and that
-- every value passes parseRuleSet.
--
-- Key:
--   itr.ruleset   one row per financial year (effective_from = 1 April, effective_to = 31 March);
--                 value = the whole ItrRuleSet JSON (lib/domain/itr-rulesets.ts), version 1:
--                 regimes.{new,old}: slabs (old regime also seniorSlabs for 60_to_79 and 80_plus),
--                 standardDeduction, rebate {limit, max, marginalRelief, notAgainst}, surcharge
--                 {bands, specialIncomeCap}, chapterVIA caps (null in the new regime), employer NPS
--                 caps, salary exemptions, houseProperty {lossSetOff, lossSetOffCap};
--                 capitalGains {rates 111A/112/112A, ltcg112aExemption, cutoverDate, earlierRates};
--                 cessRate; interest (234A/234B/234C: ratePerMonth, advanceTaxThreshold,
--                 shortfall234BPercent, instalments with 12%/36% safe harbours, presumptiveInstalment);
--                 rounding (s.288A / s.288B); sections (1961 ↔ 2025 numbering).
--                 Amounts are RUPEES; rates are percentages (12.5 = 12.5%).
--   Rows: FY 2024-25 (AY 2025-26, 1961 Act; capital-gains rates change on 23 Jul 2024),
--         FY 2025-26 (AY 2026-27, 1961 Act), tax year 2026-27 (Income-tax Act, 2025; slabs unchanged).

insert into public.statutory_parameters
  (key, value, effective_from, effective_to, statute, section_ref, source_ref, notes, verified)
